24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.advice.CityOwnerLimitException;
35	import org.springframework.samples.petclinic.rest.advice.DailyOwnerRegistrationLimitException;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    /**
63	     * The maximum number of owners that may be registered on any single day (by registration date).
64	     * Once this many owners already carry today's registration date, further creation is rejected.
65	     */
66	    private static final int MAX_OWNERS_PER_DAY = 20;
67	
68	    /**
69	     * The maximum number of owners permitted in any single city. Once a city already contains
70	     * this many owners, creating a further owner in that city is rejected. Cities are matched
71	     * ignoring letter case.
72	     */
73	    private static final int MAX_OWNERS_PER_CITY = 8;
74	
75	    /**
76	     * The number of owners, counted from the very first ever created, that receive the
77	     * {@code FOUNDING} membership tier. Owners created once this many already exist receive
78	     * the {@code STANDARD} tier instead.
79	     */
80	    private static final int FOUNDING_MEMBERSHIP_LIMIT = 100;
81	
82	    private final ClinicService clinicService;
83	
84	    private final OwnerMapper ownerMapper;
85	
86	    private final PetMapper petMapper;
87	
88	    private final VisitMapper visitMapper;
89	
90	    public OwnerRestControllerV1(ClinicService clinicService,
91	                                 OwnerMapper ownerMapper,
92	                                 PetMapper petMapper,
93	                                 VisitMapper visitMapper) {
94	        this.clinicService = clinicService;
95	        this.ownerMapper = ownerMapper;
96	        this.petMapper = petMapper;
97	        this.visitMapper = visitMapper;
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
103	        Collection<Owner> owners;
104	        if (lastName != null) {
105	            owners = this.clinicService.findOwnerByLastName(lastName);
106	        } else {
107	            owners = this.clinicService.findAllOwners();
108	        }
109	        if (owners.isEmpty()) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
118	        Owner owner = this.clinicService.findOwnerById(ownerId);
119	        if (owner == null) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
128	        HttpHeaders headers = new HttpHeaders();
129	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
130	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
131	        if (owner.getRegistrationDate() == null) {
132	            owner.setRegistrationDate(LocalDate.now());
133	        }
134	        if (isDailyRegistrationLimitReached()) {
135	            throw new DailyOwnerRegistrationLimitException(
136	                "The maximum of " + MAX_OWNERS_PER_DAY
137	                    + " owners that may be registered today has already been reached");
138	        }
139	        if (isDuplicateTelephone(owner)) {
140	            throw new DuplicateOwnerException("An owner with telephone "
141	                + owner.getTelephone() + " already exists");
142	        }
143	        if (isDuplicateEmail(owner)) {
144	            throw new DuplicateOwnerException("An owner with email "
145	                + owner.getEmail() + " already exists");
146	        }
147	        if (isCityOwnerLimitReached(owner.getCity())) {
148	            throw new CityOwnerLimitException("The city " + owner.getCity()
149	                + " already contains the maximum of " + MAX_OWNERS_PER_CITY + " owners");
150	        }
151	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
152	        owner.setMembershipNumber(membershipNumber);
153	        owner.setMembershipTier(membershipNumber <= FOUNDING_MEMBERSHIP_LIMIT ? "FOUNDING" : "STANDARD");
154	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
155	        owner.setCity(resolveCity(owner.getCity()));
156	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
157	        this.clinicService.saveOwner(owner);
158	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
159	        headers.setLocation(UriComponentsBuilder.newInstance()
160	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
161	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
162	    }
163	
164	    /**
165	     * Determines whether the maximum number of owner registrations permitted for today has
166	     * already been reached. Owners are counted by registration date, comparing against the
167	     * current day, so the limit resets at midnight.
168	     *
169	     * @return {@code true} if at least {@link #MAX_OWNERS_PER_DAY} owners already carry today's
170	     *         registration date
171	     */
172	    private boolean isDailyRegistrationLimitReached() {
173	        LocalDate today = LocalDate.now();
174	        long registeredToday = this.clinicService.findAllOwners().stream()
175	            .filter(existing -> today.equals(existing.getRegistrationDate()))
176	            .count();
177	        return registeredToday >= MAX_OWNERS_PER_DAY;
178	    }
179	
180	    /**
181	     * Determines whether the given city already contains the maximum number of owners permitted
182	     * per city. Owners are counted by matching their city ignoring letter case. A {@code null}
183	     * city is never considered to have reached the limit.
184	     *
185	     * @param city the city of the owner about to be created
186	     * @return {@code true} if at least {@link #MAX_OWNERS_PER_CITY} owners already reside in the
187	     *         given city
188	     */
189	    private boolean isCityOwnerLimitReached(String city) {
190	        if (city == null) {
191	            return false;
192	        }
193	        long ownersInCity = this.clinicService.findAllOwners().stream()
194	            .filter(existing -> existing.getCity() != null
195	                && existing.getCity().equalsIgnoreCase(city))
196	            .count();
197	        return ownersInCity >= MAX_OWNERS_PER_CITY;
198	    }
199	
200	    /**
201	     * Determines whether any other owner already uses the candidate's telephone number.
202	     * The comparison ignores letter case and surrounding or repeated whitespace.
203	     *
204	     * @param candidate the owner about to be created
205	     * @return {@code true} if an owner with the same telephone is already present in the data store
206	     */
207	    private boolean isDuplicateTelephone(Owner candidate) {
208	        String telephone = normalizeTelephone(candidate.getTelephone());
209	        return this.clinicService.findAllOwners().stream()
210	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
211	    }
212	
213	    /**
214	     * Canonicalises a telephone number by stripping every character that is not a digit
215	     * (for example spaces, dashes and parentheses), so that {@code "(613) 555-0100"} and
216	     * {@code "6135550100"} are treated as the same number. This is the form persisted for
217	     * an owner and used for the telephone-uniqueness check.
218	     *
219	     * @param telephone the raw telephone value, possibly {@code null}
220	     * @return the digits-only telephone, or {@code null} if {@code telephone} was {@code null}
221	     */
222	    private static String normalizeTelephone(String telephone) {
223	        if (telephone == null) {
224	            return null;
225	        }
226	        return telephone.replaceAll("[^0-9]", "");
227	    }
228	
229	    /**
230	     * Determines whether any other owner already uses the candidate's email address.
231	     * An absent or blank email is never considered a duplicate. The comparison ignores
232	     * letter case and surrounding or repeated whitespace.
233	     *
234	     * @param candidate the owner about to be created
235	     * @return {@code true} if an owner with the same email is already present in the data store
236	     */
237	    private boolean isDuplicateEmail(Owner candidate) {
238	        String email = normalize(candidate.getEmail());
239	        if (email == null || email.isBlank()) {
240	            return false;
241	        }
242	        return this.clinicService.findAllOwners().stream()
243	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
244	    }
245	
246	    /**
247	     * Builds the customer code for a newly created owner, formatted as
248	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
249	     * owners already present in the same city, zero-padded to four digits
250	     * (e.g. {@code 'LONDON-0007'}). Cities are matched ignoring letter case.
251	     *
252	     * @param city the city of the owner about to be created
253	     * @return the formatted customer code
254	     */
255	    /**
256	     * Resolves the city name to store for a newly created owner. The supplied city is
257	     * normalised to title case (each word's first letter upper-cased, the rest lower-cased),
258	     * so that {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}.
259	     * However, if an owner already exists in that city (matched ignoring letter case), that
260	     * existing owner's exact spelling of the city is reused instead, so a single canonical
261	     * spelling is kept per city (for example an existing {@code "McFarland"} is preserved
262	     * rather than being flattened to {@code "Mcfarland"}).
263	     *
264	     * @param city the raw city supplied for the owner about to be created
265	     * @return the existing owner's spelling if the city is already known, otherwise the
266	     *         title-cased city; {@code null} if {@code city} was {@code null}
267	     */
268	    private String resolveCity(String city) {
