307	     * ignoring letter case. This is evaluated before the new owner is saved, so it reflects
308	     * the number of <em>other</em> owners carrying that last name at creation time.
309	     *
310	     * @param lastName the last name of the owner about to be created
311	     * @return the number of existing owners with the same last name; {@code 0} if the last
312	     *         name is {@code null}
313	     */
314	    private int countNamesakes(String lastName) {
