331	    /**
332	     * Canonicalises a value for duplicate detection so that comparisons ignore letter
333	     * case and surrounding or repeated whitespace. Surrounding whitespace is stripped,
334	     * any run of internal whitespace is collapsed to a single space, and the result is
335	     * lower-cased. For example {@code "  john   smith "} and {@code "John Smith"} both
336	     * normalise to {@code "john smith"}.
337	     *
338	     * @param value the raw value, possibly {@code null}
339	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
340	     */
341	    private static String normalize(String value) {
342	        if (value == null) {
343	            return null;
344	        }
